                f"{row_where}.stable_counts must contain one count per "
                "threshold"
            )
        for count_index, (count, left_count, right_count) in enumerate(
            zip(
                stable_counts,
                left_row["stable_counts"],
                right_row["stable_counts"],
            )
        ):
